'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { build } = require('../../tools/Probar-AA-Energia');

const now = 1000;
// Synthetic fields shaped like the Carlinkit template. Expected output was
// generated by its original Java builder for the same values.
const template = Buffer.from('ba011c0a161a0408c0b802220408bcf604350000803f3d0000a04112020801', 'hex');
const sample = fields => ({ status: 'sample', sampledAt: now, freshForMs: 50, fields });
function records() {
    return new Map([
        ['batteryEnergyHv', sample({ availableWh: 60500, capacityWh: 80700 })],
        ['displayRangeElectricVehicle', sample({ displayRangeElectricVehicle: 347 })],
        ['ExteriorTemperature', sample({ temperatureExterior: 70 })],
        ['statusBatteryTemperature', sample({ actualValueTemperatureHighVoltageStorage: 77 })]
    ]);
}

test('the offline i4 sensor payloads match the Carlinkit Java output', () => {
    const result = build(template, records(), now, 10);
    assert.equal(result.fuel.toString('hex'), '3207084b10db021800');
    assert.equal(result.model.toString('hex'),
        'ba01260a201a0408d4d803220408bcf60435cdcc9c3f3d0000a0c0450000d841420308863f12020801');
    assert.equal(result.state.reserveWh, 8070);
    assert.equal(result.state.outside, -5);
});

test('a missing range is omitted and a real zero energy sets low battery', () => {
    const input = new Map([['batteryEnergyHv', sample({ availableWh: 0, capacityWh: 80700 })]]);
    const result = build(template, input, now, 10);
    assert.equal(result.fuel.toString('hex'), '320408001801');
    assert.equal(result.state.percent, 0);
    assert.equal(result.state.rangeKm, undefined);
    assert.equal(result.state.batteryTemperature, undefined);
    assert.equal(result.model.includes(Buffer.from('3d0000a041', 'hex')), false);
});

test('the replay suppresses models from stale or inconsistent energy and rejects broken templates', () => {
    assert.equal(build(template, records(), now + 50, 10), null);
    const input = records();
    input.set('batteryEnergyHv', sample({ availableWh: 10000, capacityWh: 5000 }));
    assert.equal(build(template, input, now, 10), null);
    assert.throws(() => build(template.slice(0, -1), records(), now, 10), /Campo de plantilla inválido/);
});
